"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["44379"],{45652(e){e.exports=JSON.parse('{"id":"FIN-1465","slug":"going-private","term":"Going Private","also_known_as":[],"difficulty":"Advanced","definition":"Going private is a transaction in which a publicly listed company is acquired and its shares are removed from the stock exchange, so it becomes privately owned.","explanation":["Going-private transactions are often carried out by private equity firms, sometimes together with the company\'s management, or by a controlling shareholder buying out the remaining public shareholders. They are frequently financed with significant debt, as leveraged buyouts.","Companies or their owners may choose to go private to escape the pressure of quarterly results, reduce the costs and disclosure requirements of being listed, make major changes away from public scrutiny, or because the buyer believes the market undervalues the company.","For example, a private equity firm might offer public shareholders a premium of 30% above the share price, buy all the shares and delist the company, aiming to improve it and sell it a few years later.","Going-private transactions raise concerns about fairness, especially when management or a controlling shareholder is involved, since they may know more about the company\'s value. Rules often require independent committees of directors, fairness opinions and shareholder approval to protect minority shareholders."],"note":"","total":1500,"prev":{"slug":"going-concern-warning","term":"Going-Concern Warning"},"next":{"slug":"goods-and-services-tax","term":"Goods and Services Tax (GST)"}}')}}]);